            <td style="color:#38bdf8;">${tensDigit}</td>
            <td style="color:#38bdf8;">${onesDigit}</td>
          </tr>
          <!-- 십의 자리 곱한 값 -->
          ${tutorCurrentStep >= 2 ? `
          <tr>
            <td></td>
            <td>-</td>
            <td class="${curPlan.focus === 'mult_tens' ? 'cell-active' : ''}" style="color:#ec4899;">${multTens}</td>
            <td></td>
          </tr>
          ` : ''}
          <!-- 십의 자리 뺀 값 및 내려쓰기 -->
          ${tutorCurrentStep >= 3 ? `
          <tr>
            <td></td>
            <td class="calc-step-line"></td>
